using Microsoft.EntityFrameworkCore;
using Npgsql.EntityFrameworkCore.PostgreSQL.Metadata;
namespace Salao.Api;
public class SalonDb(DbContextOptions<SalonDb> options) : DbContext(options) {
 public DbSet<Client> Clients => Set<Client>(); public DbSet<CatalogService> Services => Set<CatalogService>(); public DbSet<Product> Products => Set<Product>(); public DbSet<Appointment> Appointments => Set<Appointment>(); public DbSet<AppointmentItem> AppointmentItems => Set<AppointmentItem>(); public DbSet<AppointmentRecord> AppointmentRecords => Set<AppointmentRecord>(); public DbSet<Receivable> Receivables => Set<Receivable>(); public DbSet<AdminCredential> AdminCredentials => Set<AdminCredential>(); public DbSet<SalonUser> SalonUsers => Set<SalonUser>(); public DbSet<MonthlyServicePackage> MonthlyPackages => Set<MonthlyServicePackage>(); public DbSet<MonthlyPackageItem> MonthlyPackageItems => Set<MonthlyPackageItem>(); public DbSet<MonthlyPackageSession> MonthlyPackageSessions => Set<MonthlyPackageSession>(); public DbSet<MonthlyPackagePayment> MonthlyPackagePayments => Set<MonthlyPackagePayment>();
 protected override void OnModelCreating(ModelBuilder b) {
  b.Entity<Client>(e=>{e.ToTable("clients");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.Property(x=>x.Name).HasMaxLength(160).IsRequired();});
  b.Entity<CatalogService>(e=>{e.ToTable("services");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.Property(x=>x.Price).HasPrecision(12,2);e.Property(x=>x.Name).HasMaxLength(180);});
  b.Entity<MonthlyServicePackage>(e=>{e.ToTable("monthly_service_packages");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.Property(x=>x.Price).HasPrecision(12,2);e.HasOne(x=>x.Client).WithMany().HasForeignKey(x=>x.ClientId);});
  b.Entity<MonthlyPackageItem>(e=>{e.ToTable("monthly_package_items");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.HasOne(x=>x.Package).WithMany(x=>x.Items).HasForeignKey(x=>x.PackageId).OnDelete(DeleteBehavior.Cascade);});
  b.Entity<MonthlyPackageSession>(e=>{e.ToTable("monthly_package_sessions");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.HasOne(x=>x.Package).WithMany(x=>x.Sessions).HasForeignKey(x=>x.PackageId).OnDelete(DeleteBehavior.Cascade);});
  b.Entity<MonthlyPackagePayment>(e=>{e.ToTable("monthly_package_payments");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.Property(x=>x.Amount).HasPrecision(12,2);e.Property(x=>x.PaymentMethod).HasMaxLength(20);e.HasOne(x=>x.Package).WithMany(x=>x.Payments).HasForeignKey(x=>x.PackageId).OnDelete(DeleteBehavior.Cascade);});
  b.Entity<Product>(e=>{e.ToTable("products");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.Property(x=>x.Price).HasPrecision(12,2);});
  b.Entity<Appointment>(e=>{e.ToTable("appointments");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.HasOne(x=>x.Client).WithMany().HasForeignKey(x=>x.ClientId);});
  b.Entity<AppointmentRecord>(e=>{e.ToTable("appointment_records");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.HasIndex(x=>x.AppointmentId).IsUnique();e.HasOne(x=>x.Appointment).WithOne(x=>x.Record).HasForeignKey<AppointmentRecord>(x=>x.AppointmentId).OnDelete(DeleteBehavior.Cascade);});
  b.Entity<AppointmentItem>(e=>{e.ToTable("appointment_items");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.Property(x=>x.UnitPrice).HasPrecision(12,2);});
  b.Entity<Receivable>(e=>{e.ToTable("receivables");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.Property(x=>x.Amount).HasPrecision(12,2);e.Property(x=>x.PaymentMethod).HasMaxLength(20);e.HasOne(x=>x.Appointment).WithMany(x=>x.Receivables).HasForeignKey(x=>x.AppointmentId);});
  b.Entity<AdminCredential>(e=>{e.ToTable("admin_credentials");e.HasKey(x=>x.Id);e.Property(x=>x.AccessCodeHash).IsRequired();e.Property(x=>x.ChangeCodeHash).IsRequired();e.Property(x=>x.SessionKey).IsRequired();});
  b.Entity<SalonUser>(e=>{e.ToTable("salon_users");e.HasKey(x=>x.Id);e.Property(x=>x.Id).UseIdentityByDefaultColumn();e.Property(x=>x.Name).HasMaxLength(160).IsRequired();e.Property(x=>x.AccessCodeHash).IsRequired();e.Property(x=>x.SessionKey).IsRequired();});
 }
}
